window.PRELOADED_CHAPTERS_C9SK["1"] = "<section class=\"chapter-section\" id=\"ch1\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः १</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">पद्यभागः (गीतिः) • शेमुषी प्रथमो भागः (Code 122)</div>\n      <h2>प्रथमः पाठः — भारतीवसन्तगीतिः</h2>\n      <p class=\"ch-author\">रचयिता: पण्डित-जानकीवल्लभ-शास्त्री (गीतिसङ्ग्रहः: ‘काकली’)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>प्रस्तुतोऽयं पाठः आधुनिकसंस्कृतसाहित्यस्य प्रख्यातस्य कवेः <strong>पण्डित-जानकीवल्लभशास्त्रिणः</strong> ‘काकली’ इति गीतिसङ्ग्रहात् सङ्कलितोऽस्ति। अत्र कविः स्वाधीनता-सङ्ग्रामस्य पृष्ठभूमौ भारतमातुः सांस्कृतिक-जागरणार्थं वाग्देवीं भगवतीं सरस्वतीं सम्बोध्य प्रार्थयते यत् सा नवीनाम् ओजस्विनीं च वीणां वादयतु, येन जनमानसे नूतना चेतना, स्वाभिमानः, सत्य-न्याय-नीतिलीना च राष्ट्रभक्तिः सञ्चारिता भवेत्।</p>\n      <p style=\"margin-top:8px;font-style:italic;color:#6b21a8;\"><strong>काव्य-सौन्दर्यम्:</strong> अस्मिन् गीते वसन्तऋतोः मनमोहकं प्राकृतिकं वातावरणम्, आम्रमञ्जरीणां सौरभम्, यमुनातीरे वेतसलतानां सौन्दर्यम्, कोकिलानां मधुरकूजनं तथा भ्रमराणां गुञ्जारवः अतिरमणीयतया चित्रितः अस्ति।</p>\n    </div>\n  </div>\n\n  <!-- Custom Educational SVG -->\n  \n  <div style=\"margin:22px 0; background:white; padding:18px; border-radius:14px; border:1.5px solid #ede9fe; box-shadow:0 3px 12px rgba(124,58,237,0.06);\">\n    <h3 style=\"font-size:1.02rem; font-weight:800; color:#5b21b6; margin-bottom:12px; display:flex; align-items:center; gap:8px; font-family:'Noto Sans Devanagari', sans-serif;\">\n      <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"2.2\"><path d=\"M9 18V5l12-2v13\"/><circle cx=\"6\" cy=\"18\" r=\"3\"/><circle cx=\"18\" cy=\"16\" r=\"3\"/></svg>\n      काव्य-दर्शनम्: सरस्वती-वीणावादनम्, वसन्त-प्रकृति-सौन्दर्यम् तथा राष्ट्रिय-नवजागरणम्\n    </h3>\n    <svg viewBox=\"0 0 780 250\" style=\"width:100%; height:auto; font-family:'Noto Sans Devanagari', system-ui, sans-serif;\">\n      <!-- Panel 1: Saraswati & Cultural Awakening -->\n      <rect x=\"15\" y=\"15\" width=\"375\" height=\"220\" rx=\"10\" fill=\"#faf5ff\" stroke=\"#ddd6fe\" stroke-width=\"1.5\"/>\n      <text x=\"32\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#5b21b6\">१. माँ भारती (सरस्वती) एवं वीणा-सङ्गीतम्:</text>\n\n      <!-- Center Veena Motif -->\n      <g transform=\"translate(40, 55)\">\n        <rect x=\"0\" y=\"0\" width=\"325\" height=\"155\" rx=\"8\" fill=\"#ffffff\" stroke=\"#ede9fe\"/>\n        <!-- Veena Representation -->\n        <ellipse cx=\"60\" cy=\"80\" rx=\"36\" ry=\"46\" fill=\"#fdf4ff\" stroke=\"#c084fc\" stroke-width=\"2\"/>\n        <ellipse cx=\"60\" cy=\"80\" rx=\"20\" ry=\"26\" fill=\"#f3e8ff\" stroke=\"#a855f7\" stroke-width=\"1.5\"/>\n        <!-- Veena Neck / Danda -->\n        <line x1=\"86\" y1=\"80\" x2=\"270\" y2=\"35\" stroke=\"#9333ea\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n        <!-- Strings -->\n        <line x1=\"86\" y1=\"78\" x2=\"268\" y2=\"33\" stroke=\"#d8b4fe\" stroke-width=\"1.2\"/>\n        <line x1=\"86\" y1=\"80\" x2=\"270\" y2=\"35\" stroke=\"#fef08a\" stroke-width=\"1.2\"/>\n        <line x1=\"86\" y1=\"82\" x2=\"272\" y2=\"37\" stroke=\"#d8b4fe\" stroke-width=\"1.2\"/>\n        <!-- Pegs / Frets -->\n        <circle cx=\"260\" cy=\"38\" r=\"4\" fill=\"#6b21a8\"/>\n        <circle cx=\"245\" cy=\"42\" r=\"4\" fill=\"#6b21a8\"/>\n        <circle cx=\"230\" cy=\"46\" r=\"4\" fill=\"#6b21a8\"/>\n        <!-- Soundwaves / Notes -->\n        <text x=\"140\" y=\"70\" font-size=\"14\" fill=\"#7c3aed\">♫</text>\n        <text x=\"180\" y=\"55\" font-size=\"18\" fill=\"#9333ea\">♪</text>\n        <text x=\"210\" y=\"80\" font-size=\"13\" fill=\"#c026d3\">♫</text>\n        <text x=\"15\" y=\"140\" font-size=\"8.8\" font-weight=\"bold\" fill=\"#6b21a8\">• ‘निनादय नवीनामये वाणि वीणाम्’</text>\n        <text x=\"175\" y=\"140\" font-size=\"8.2\" fill=\"#475569\">— नवचेतना, स्वाभिमानः, स्वाधीनता</text>\n      </g>\n\n      <!-- Panel 2: Vasanta Season & Yamuna Banks -->\n      <rect x=\"405\" y=\"15\" width=\"360\" height=\"220\" rx=\"10\" fill=\"#f0fdf4\" stroke=\"#bbf7d0\" stroke-width=\"1.5\"/>\n      <text x=\"422\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#166534\">२. वसन्त-ऋतोः प्राकृतिकं वैभवम्:</text>\n\n      <g transform=\"translate(420, 55)\">\n        <rect x=\"0\" y=\"0\" width=\"330\" height=\"155\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dcfce7\"/>\n        <!-- Elements of Vasanta -->\n        <!-- 1. Rasalah (Mangoes) -->\n        <rect x=\"12\" y=\"15\" width=\"145\" height=\"58\" rx=\"6\" fill=\"#fef9c3\" stroke=\"#fde047\"/>\n        <text x=\"20\" y=\"32\" font-size=\"9\" font-weight=\"bold\" fill=\"#854d0e\">सरसाः रसालाः (आम्रमञ्जरी):</text>\n        <text x=\"20\" y=\"47\" font-size=\"7.8\" fill=\"#713f12\">• मधुरमञ्जरीपिञ्जरीभूतमालाः</text>\n        <text x=\"20\" y=\"60\" font-size=\"7.8\" fill=\"#713f12\">• कोकिलाकाकलीनां कूजनम्</text>\n\n        <!-- 2. Yamuna & Madhavi Creeper -->\n        <rect x=\"168\" y=\"15\" width=\"150\" height=\"58\" rx=\"6\" fill=\"#eff6ff\" stroke=\"#bfdbfe\"/>\n        <text x=\"176\" y=\"32\" font-size=\"9\" font-weight=\"bold\" fill=\"#1e40af\">कलिन्दात्मजा (यमुना):</text>\n        <text x=\"176\" y=\"47\" font-size=\"7.8\" fill=\"#1e3a8a\">• सवानीरतीरे (वेत्रलतासहिते)</text>\n        <text x=\"176\" y=\"60\" font-size=\"7.8\" fill=\"#1e3a8a\">• नता मधुमाधवीनां पङ्क्तिः</text>\n\n        <!-- 3. Malay Maruta & Bhramara -->\n        <rect x=\"12\" y=\"82\" width=\"306\" height=\"60\" rx=\"6\" fill=\"#fdf4ff\" stroke=\"#f0abfc\"/>\n        <text x=\"20\" y=\"100\" font-size=\"9\" font-weight=\"bold\" fill=\"#86198f\">मलयमारुतः एवं भ्रमराणाम् अलि-ततिः:</text>\n        <text x=\"20\" y=\"116\" font-size=\"7.8\" fill=\"#701a75\">• मन्दं मन्दं वहति समीरे कलिन्दात्मजायाः तीरे</text>\n        <text x=\"20\" y=\"130\" font-size=\"8\" font-weight=\"bold\" fill=\"#a21caf\">• मलिनां ततिमवलोक्य वीणां निनादय (भ्रमराणां गुञ्जारवः)</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (NCERT Exercises & CBSE Marking Rubrics 2026-27)</div>\n\n  <!-- अभ्यासः १ -->\n  <div class=\"q-card\" id=\"c9sk_ch1_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch1_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरं लिखत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः (Only 1-2 words as per CBSE Rubric)</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितानां प्रश्नानाम् उत्तराणि एकपदेन लिखत:<br>\n        (क) कविः कां सम्बोधयति?<br>\n        (ख) कविः वाणीं कां वादयितुं प्रार्थयति?<br>\n        (ग) कीदृशीं वीणां निनादयितुं प्रार्थयति?<br>\n        (घ) गीतिं कथं गातुं कथयति?<br>\n        (ङ) सरसाः रसालाः कदा लसन्ति?\n      </div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क)</strong> <span class=\"ans-highlight\">वाणीम्</span> (सरस्वतीम्)</p>\n            <p><strong>(ख)</strong> <span class=\"ans-highlight\">वीणाम्</span></p>\n            <p><strong>(ग)</strong> <span class=\"ans-highlight\">नवीनाम्</span></p>\n            <p><strong>(घ)</strong> <span class=\"ans-highlight\">मृदुम्</span> (ललितनीतिलीनाम्)</p>\n            <p><strong>(ङ)</strong> <span class=\"ans-highlight\">वसन्ते</span> (वसन्तसमये)</p>\n          </div>\n          <div class=\"hi-trans\">\n            <strong>हिन्दी व्याख्या एवं व्याकरण-टिप्पणी:</strong><br>\n            • (क) कवि देवी सरस्वती (वाणी) को सम्बोधित करता है।<br>\n            • (ख) कवि वाणी से वीणा बजाने की प्रार्थना करता है।<br>\n            • (ग) वह ओज और चेतना जगाने वाली नवीन वीणा बजाने का अनुरोध करता है।<br>\n            • (घ) कवि सुंदर नीतियों से परिपूर्ण कोमल और मधुर गीत गाने को कहता है।<br>\n            • (ङ) रसीले आम के वृक्ष वसंत ऋतु में सुशोभित होते हैं।\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(क) ‘वाणीम्’ शुद्ध द्वितीया-एकवचन-पदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ख) ‘वीणाम्’ शुद्ध पदस्य लेखनाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ग) ‘नवीनाम्’ विशेषणपदस्य शुद्धरूपाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(घ) ‘मृदुम्’ क्रियाविशेषणपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ङ) ‘वसन्ते’ सप्तमी-विभक्तियुक्तपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः २ -->\n  <div class=\"q-card\" id=\"c9sk_ch1_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch1_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-घ) — पूर्णवाक्येन उत्तरं लिखत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः (Full Sentence with Subject-Verb Agreement)</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितानां प्रश्नानाम् उत्तराणि संस्कृतभाषया पूर्णवाक्येन लिखत:<br>\n        (क) कविः वाणीं किं कथयति?<br>\n        (ख) वसन्ते किं भवति?<br>\n        (ग) सलिलं तव वीणामाकर्ण्य कथम् उच्चलेत्?<br>\n        (घ) कविः भगवतीं भारतीं कस्याः तीरे मधुमाधवीनां नतां पङ्क्तिम् अवलोक्य वीणां वादयितुं कथयति?\n      </div>\n      <div class=\"q-marks\">१ × ४ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क)</strong> कविः वाणीं कथयति यत्— अयि वाणि! नवीनां वीणां निनादय, ललितनीतिलीनां मृदुं गीतिं च गाय।</p>\n            <p><strong>(ख)</strong> वसन्ते मधुरमञ्जरीपिञ्जरीभूतमालाः सरसाः रसालाः लसन्ति, ललितकोकिलाकाकलीनां कलापाः च विलसन्ति।</p>\n            <p><strong>(ग)</strong> तव ओजस्विनीं वीणामाकर्ण्य नदीनां कान्तसलिलं सलीलम् (क्रीडासहितम्) उच्चलेत्।</p>\n            <p><strong>(घ)</strong> कविः भगवतीं भारतीं कलिन्दात्मजायाः (यमुनायाः) सवानीरतीरे नतां मधुमाधवीनां पङ्क्तिम् अवलोक्य वीणां वादयितुं कथयति।</p>\n          </div>\n          <div class=\"hi-trans\">\n            <strong>हिन्दी व्याख्या:</strong><br>\n            • (क) कवि वाणी (सरस्वती) से प्रार्थना करता है कि हे माँ! नई वीणा बजाओ और सुंदर नीतियों से युक्त मधुर गीत का गायन करो।<br>\n            • (ख) वसंत ऋतु में पीली मंजरियों से युक्त रसीले आम के पेड़ सुशोभित होते हैं तथा सुंदर कूकने वाली कोयलों के समूह मधुर गान करते हैं।<br>\n            • (ग) माँ सरस्वती की वीणा का पावन नाद सुनकर शांत और निर्मल जल क्रीड़ा करता हुआ उछलने लगता है।<br>\n            • (घ) कवि भगवती सरस्वती से यमुना नदी के बेंत की लताओं से घिरे तट पर झुकी हुई सुंदर मालती (मधुमाधवी) लताओं की पंक्तियों को देखकर वीणा वादन करने को कहता है।\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(क) पूर्णवाक्ये शुद्ध-कर्तृ-क्रिया-सहितं कथनप्रतिपादनम्</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ख) रसाल-कोकिला-उभयोः यथार्थोल्लेखेन वाक्यरचना</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ग) ‘सलीलमुच्छलेत्’ इत्यस्य शुद्धान्वयप्रयोगः</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(घ) ‘कलिन्दात्मजायाः सवानीरतीरे’ शुद्ध-विभक्ति-प्रयोगः</span><span class=\"marking-marks\">१ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ३ -->\n  <div class=\"q-card\" id=\"c9sk_ch1_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch1_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — पर्यायपदानां मेलनम्</span>\n        <span class=\"word-limit-pill\">स्तम्भद्वयस्य यथार्थमेलनम्</span>\n      </div>\n      <div class=\"q-text\">\n        ‘क’ स्तम्भे पदानि, ‘ख’ स्तम्भे तेषां पर्यायपदानि दत्तानि। तानि चित्वा पदानां समक्षे लिखत:<br>\n        <strong>‘क’ स्तम्भः:</strong> (क) सरस्वती, (ख) आम्रम्, (ग) पवनः, (घ) तटे, (ङ) भ्रमराणाम्<br>\n        <strong>‘ख’ स्तम्भः:</strong> तीरे, अलीनाम्, समीरः, वाणी, रसालः\n      </div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <table style=\"width:100%; border-collapse:collapse; margin:10px 0; font-size:0.9rem;\">\n            <thead>\n              <tr style=\"background:#f5f3ff; text-align:left; border-bottom:2px solid #ddd6fe;\">\n                <th style=\"padding:10px; color:#5b21b6;\">‘क’ स्तम्भः (मूलपदम्)</th>\n                <th style=\"padding:10px; color:#5b21b6;\">‘ख’ स्तम्भः (पर्यायपदम्)</th>\n                <th style=\"padding:10px; color:#5b21b6;\">हिन्दी अर्थः</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px; font-weight:700;\">(क) सरस्वती</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">वाणी</td>\n                <td style=\"padding:9px; color:#64748b;\">विद्या की देवी माँ सरस्वती</td>\n              </tr>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px; font-weight:700;\">(ख) आम्रम्</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">रसालः</td>\n                <td style=\"padding:9px; color:#64748b;\">आम का फल / वृक्ष</td>\n              </tr>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px; font-weight:700;\">(ग) पवनः</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">समीरः</td>\n                <td style=\"padding:9px; color:#64748b;\">वायु / हवा</td>\n              </tr>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px; font-weight:700;\">(घ) तटे</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">तीरे</td>\n                <td style=\"padding:9px; color:#64748b;\">किनारे पर</td>\n              </tr>\n              <tr>\n                <td style=\"padding:9px; font-weight:700;\">(ङ) भ्रमराणाम्</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">अलीनाम्</td>\n                <td style=\"padding:9px; color:#64748b;\">भौरों का</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् शुद्ध-पर्यायपद-मेलनाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ४ -->\n  <div class=\"q-card\" id=\"c9sk_ch1_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch1_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — संस्कृतभाषया वाक्यरचना</span>\n        <span class=\"word-limit-pill\">व्याकरणसम्मत शुद्धवाक्यम्</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितानि पदानि प्रयुज्य संस्कृतभाषया वाक्यरचनां कुरुत:<br>\n        (क) निनादय<br>\n        (ख) मन्दमन्दम्<br>\n        (ग) मारुतः<br>\n        (घ) सलिलम्<br>\n        (ङ) सुमनः\n      </div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क) निनादय (बजाओ):</strong><br>\n            वाक्यम्: <span class=\"ans-highlight\">अयि वाणि! नवीनां वीणां निनादय।</span><br>\n            <em>(हिन्दी: हे सरस्वती! नई वीणा को बजाओ।)</em></p>\n\n            <p style=\"margin-top:10px;\"><strong>(ख) मन्दमन्दम् (धीरे-धीरे):</strong><br>\n            वाक्यम्: <span class=\"ans-highlight\">उद्याने मलयमारुतः मन्दमन्दं वहति।</span><br>\n            <em>(हिन्दी: बगीचे में मलय समीर धीरे-धीरे बहता है।)</em></p>\n\n            <p style=\"margin-top:10px;\"><strong>(ग) मारुतः (हवा/वायु):</strong><br>\n            वाक्यम्: <span class=\"ans-highlight\">वसन्तऋतौ सुगन्धितः मारुतः सर्वान् आह्लादयति।</span><br>\n            <em>(हिन्दी: वसंत ऋतु में सुगंधित वायु सबको आनंदित करती है।)</em></p>\n\n            <p style=\"margin-top:10px;\"><strong>(घ) सलिलम् (जल/पानी):</strong><br>\n            वाक्यम्: <span class=\"ans-highlight\">कलिन्दात्मजायाः सलिलं निर्मलं शीतलं च भवति।</span><br>\n            <em>(हिन्दी: यमुना नदी का जल स्वच्छ और शीतल होता है।)</em></p>\n\n            <p style=\"margin-top:10px;\"><strong>(ङ) सुमनः (फूल/पुष्प):</strong><br>\n            वाक्यम्: <span class=\"ans-highlight\">ललितायां लतायां मनोहरः सुमनः विकसति।</span><br>\n            <em>(हिन्दी: सुंदर लता पर मनोहर फूल खिलता है।)</em></p>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पदानां सार्थकेन व्याकरणसम्मत-प्रयोगेण प्रतिवाक्यम्</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ५ -->\n  <div class=\"q-card\" id=\"c9sk_ch1_q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch1_q5')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ५ — प्रथमश्लोकस्य भावार्थः</span>\n        <span class=\"word-limit-pill\">हिन्दीभाषया आङ्ग्लभाषया वा आशयलेखनम्</span>\n      </div>\n      <div class=\"q-text\">\n        प्रथमश्लोकस्य आशयं हिन्दीभाषया आङ्ग्लभाषया वा लिखत:<br>\n        <em>‘निनादय नवीनामये वाणि वीणाम्<br>\n        मृदुं गाय गीतिं ललितनीतिलीनाम्।<br>\n        मधुरमञ्जरीपिञ्जरीभूतमालाः<br>\n        वसन्ते लसन्तीह सरसा रसालाः<br>\n        कलापाः ललितकोकिलाकाकलीनाम्॥’</em>\n      </div>\n      <div class=\"q-marks\">३ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <p><strong>१. हिन्दीभाषया आशयः (Bhavarth in Hindi):</strong></p>\n          <div class=\"hi-trans\" style=\"margin-top:6px; line-height:1.75;\">\n            हे माँ सरस्वती! आप अपनी नवीन और ओजस्वी वीणा का वादन कीजिए तथा सुंदर और कल्याणकारी नीतियों से परिपूर्ण मधुर गीत का गान कीजिए।<br><br>\n            इस वसंत ऋतु में पीले-पीले परागकणों और मधुर मंजरियों से आच्छादित रसीले आम के वृक्षों की कतारें अत्यंत शोभायमान हो रही हैं, और उन पर मधुर कूक करने वाली सुंदर कोयलों के झुंड मनमोहक गान कर रहे हैं। कवि माँ शारदा से प्रार्थना करता है कि इस मनोहर प्राकृतिक वातावरण में वह जनमानस में नव-स्फूर्ति, स्वाधीनता, सांस्कृतिक गरिमा और देशप्रेम का अलौकिक संगीत भर दें।\n          </div>\n\n          <p style=\"margin-top:14px;\"><strong>२. English Purport (आङ्ग्लभाषया आशयः):</strong></p>\n          <div style=\"background:#faf5ff; border-left:3px solid #7c3aed; padding:10px 14px; border-radius:0 8px 8px 0; font-size:0.88rem; color:#4c1d95; line-height:1.7;\">\n            \"O Goddess Saraswati! Resonate Thy pristine, inspiring lyre (Veena) and sing a melodious song enriched with righteous, sublime values. In this vibrant spring season, rows of luscious mango trees laden with golden, honey-sweet blossoms are radiating splendour, while flocks of charming cuckoos warble sweetly in harmony. O Mother Divine, awaken the hearts of the nation with the sublime melody of freedom, righteous ideals, and patriotic consciousness.\"\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कवेः मूल-आशयस्य एवं प्रकृतेः वर्णनस्य सम्यक् प्रतिपादनम्</span><span class=\"marking-marks\">१.५ अंकाः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषायाः सरलता, स्पष्टता एवं साहित्यिक-सौष्ठवम्</span><span class=\"marking-marks\">१.५ अंकाः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ६ -->\n  <div class=\"q-card\" id=\"c9sk_ch1_q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch1_q6')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ६ — विलोमपदानि लिखत</span>\n        <span class=\"word-limit-pill\">सटीक विलोमपदानि</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितपदानां विलोमपदानि लिखत:<br>\n        (क) कठोरम्<br>\n        (ख) कटु<br>\n        (ग) शीघ्रम्<br>\n        (घ) प्राचीनम्<br>\n        (ङ) नीरसः\n      </div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क) कठोरम्</strong> $\times$ <span class=\"ans-highlight\">मृदुम् / कोमलम्</span></p>\n            <p><strong>(ख) कटु</strong> $\times$ <span class=\"ans-highlight\">मधुरम्</span></p>\n            <p><strong>(ग) शीघ्रम्</strong> $\times$ <span class=\"ans-highlight\">मन्दम् / शनैः / मन्दमन्दम्</span></p>\n            <p><strong>(घ) प्राचीनम्</strong> $\times$ <span class=\"ans-highlight\">नवीनम् / अर्वाचीनम्</span></p>\n            <p><strong>(ङ) नीरसः</strong> $\times$ <span class=\"ans-highlight\">सरसः</span></p>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् शुद्ध-विलोमपदलेखनाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #7c3aed;\">\n        <div class=\"cbq-type\" style=\"color:#7c3aed;\">योग्यता-आधारितः प्रश्नः (NEP 2020 Competency HOTS Question)</div>\n        <div class=\"cbq-question\">\n          <strong>प्रश्नः:</strong> ‘भारतीवसन्तगीतिः’ इति गीते कविः प्रकृतेः सौन्दर्यं वर्णयन् कीदृशीं राष्ट्रिय-चेतनां जाग्रतीं च उद्घोषयति? (शब्द-सीमा: ३०-४० शब्दाः | अंकाः: २)\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\">\n          <p>अस्मिन् पाठे कविः स्वाधीनता-आन्दोलनस्य पृष्ठभूमौ प्रकृतेः नववसन्तस्य माधुर्येण सह देशभक्तेः नूतनजागरणस्य च आह्वानं करोति। यथा वसन्ते मञ्जरीभिः प्रकृतिः पुनर्नवीकृता भवति, तथैव सरस्वत्याः वीणावादनस्य ओजस्वी-नादेन भारतीयजनेषु नवीना ऊर्जा, स्वाभिमानः, नीतिनिष्ठा राष्ट्रभक्तिश्च सञ्चारिता भवेदिति कवेः मूल-उद्देश्यम् अस्ति।</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Chapter Nav Buttons -->\n  <div class=\"chapter-nav-btns\">\n    <div></div>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\">अग्रिमः पाठः: स्वर्णकाकः (Ch 2) →</button>\n  </div>\n</section>";

window.PRELOADED_CHAPTERS_C9SK["2"] = "<section class=\"chapter-section\" id=\"ch2\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः २</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">गद्यभागः (नीतिकथा) • शेमुषी प्रथमो भागः (Code 122)</div>\n      <h2>द्वितीयः पाठः — स्वर्णकाकः</h2>\n      <p class=\"ch-author\">रचयिता: श्रीपद्मशास्त्री (कथासङ्ग्रहः: ‘विश्वकथाशतकम्’ - बर्मा/म्यांमारदेशस्य लोककथा)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>प्रस्तुतोऽयं पाठः श्रीपद्मशास्त्रिणा विरचितस्य ‘विश्वकथाशतकम्’ इति कथासङ्ग्रहात् गृहीतोऽस्ति। एषा म्यांमार (बर्मा) देशस्य एका प्रसिद्धा श्रेष्ठतमा च लोककथा वर्तते। अस्यां कथायां लोभस्य दुष्परिणामः तथा त्यागस्य, विनम्रतायाः, सन्तोषस्य च शुभफलम् एका विचित्रकाकमाध्यमेन अतिरोचकशैल्या वर्णितमस्ति।</p>\n      <p style=\"margin-top:8px;font-style:italic;color:#6b21a8;\"><strong>नीति-शिक्षा:</strong> मनुष्येण लोभः कदापि न करणीयः। यतः ‘लोभः पापस्य कारणम्’ भवति। सन्तोषी, विनम्रः च मानवः एव संसारे सुखं, मानं, वास्तविकं वैभवं च प्राप्नोति।</p>\n    </div>\n  </div>\n\n  <!-- Custom Educational SVG -->\n  \n  <div style=\"margin:22px 0; background:white; padding:18px; border-radius:14px; border:1.5px solid #ede9fe; box-shadow:0 3px 12px rgba(124,58,237,0.06);\">\n    <h3 style=\"font-size:1.02rem; font-weight:800; color:#5b21b6; margin-bottom:12px; display:flex; align-items:center; gap:8px; font-family:'Noto Sans Devanagari', sans-serif;\">\n      <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#d97706\" stroke-width=\"2.2\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg>\n      कथा-दर्शनम्: स्वर्णकाकः, सोपान-मञ्जूषा-चयनम् एवं लोभस्य दुष्परिणामः\n    </h3>\n    <svg viewBox=\"0 0 780 250\" style=\"width:100%; height:auto; font-family:'Noto Sans Devanagari', system-ui, sans-serif;\">\n      <!-- Panel 1: Swarnakaka & Golden Palace -->\n      <rect x=\"15\" y=\"15\" width=\"375\" height=\"220\" rx=\"10\" fill=\"#fffbeb\" stroke=\"#fde68a\" stroke-width=\"1.5\"/>\n      <text x=\"32\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#b45309\">१. स्वर्णपक्ष-काकः एवं सुवर्णमय-प्रासादः:</text>\n\n      <g transform=\"translate(30, 52)\">\n        <rect x=\"0\" y=\"0\" width=\"345\" height=\"162\" rx=\"8\" fill=\"#ffffff\" stroke=\"#fef3c7\"/>\n        <!-- Golden Crow Motif -->\n        <circle cx=\"50\" cy=\"50\" r=\"24\" fill=\"#fef08a\" stroke=\"#eab308\" stroke-width=\"2\"/>\n        <polygon points=\"74,48 88,52 74,56\" fill=\"#cbd5e1\" stroke=\"#94a3b8\" stroke-width=\"1.5\"/> <!-- Silver Beak -->\n        <ellipse cx=\"40\" cy=\"70\" rx=\"20\" ry=\"12\" fill=\"#fde047\" stroke=\"#ca8a04\"/>\n        <text x=\"24\" y=\"54\" font-size=\"10\" font-weight=\"bold\" fill=\"#713f12\">स्वर्णकाकः</text>\n        <text x=\"96\" y=\"44\" font-size=\"8.8\" font-weight=\"bold\" fill=\"#b45309\">• स्वर्णपक्षः, रजतचञ्चुः</text>\n        <text x=\"96\" y=\"58\" font-size=\"8\" fill=\"#475569\">(सोने के पंख, चांदी की चोंच)</text>\n        <text x=\"96\" y=\"72\" font-size=\"8.2\" fill=\"#713f12\">• न्यग्रोधवृक्षस्योपरि स्वर्णमयः प्रासादः</text>\n\n        <!-- Three Staircases Matrix -->\n        <rect x=\"12\" y=\"92\" width=\"100\" height=\"58\" rx=\"5\" fill=\"#fef9c3\" stroke=\"#fde047\"/>\n        <text x=\"18\" y=\"108\" font-size=\"8\" font-weight=\"bold\" fill=\"#854d0e\">१. स्वर्णसोपानम्</text>\n        <text x=\"18\" y=\"122\" font-size=\"7.2\" fill=\"#713f12\">सोने की सीढ़ी</text>\n        <text x=\"18\" y=\"136\" font-size=\"7.2\" fill=\"#166534\">विनम्रायै प्रदत्तम्</text>\n\n        <rect x=\"122\" y=\"92\" width=\"100\" height=\"58\" rx=\"5\" fill=\"#f1f5f9\" stroke=\"#cbd5e1\"/>\n        <text x=\"128\" y=\"108\" font-size=\"8\" font-weight=\"bold\" fill=\"#334155\">२. रजतसोपानम्</text>\n        <text x=\"128\" y=\"122\" font-size=\"7.2\" fill=\"#475569\">चांदी की सीढ़ी</text>\n        <text x=\"128\" y=\"136\" font-size=\"7.2\" fill=\"#475569\">मध्यम-विकल्पः</text>\n\n        <rect x=\"232\" y=\"92\" width=\"100\" height=\"58\" rx=\"5\" fill=\"#ffedd5\" stroke=\"#fed7aa\"/>\n        <text x=\"238\" y=\"108\" font-size=\"8\" font-weight=\"bold\" fill=\"#9a3412\">३. ताम्रसोपानम्</text>\n        <text x=\"238\" y=\"122\" font-size=\"7.2\" fill=\"#9a3412\">तांबे की सीढ़ी</text>\n        <text x=\"238\" y=\"136\" font-size=\"7.2\" fill=\"#b91c1c\">लुब्धायै दत्तम</text>\n      </g>\n\n      <!-- Panel 2: The Two Girls & Two Outcomes -->\n      <rect x=\"405\" y=\"15\" width=\"360\" height=\"220\" rx=\"10\" fill=\"#f8fafc\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"/>\n      <text x=\"422\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#0f172a\">२. सन्तोषः vs लोभः (कर्मफल-सिद्धान्तः):</text>\n\n      <g transform=\"translate(420, 52)\">\n        <!-- Box A: Vinamra Balika -->\n        <rect x=\"0\" y=\"0\" width=\"160\" height=\"162\" rx=\"6\" fill=\"#f0fdf4\" stroke=\"#86efac\"/>\n        <text x=\"10\" y=\"20\" font-size=\"8.8\" font-weight=\"bold\" fill=\"#166534\">विनम्रा निर्धना बालिका:</text>\n        <text x=\"10\" y=\"36\" font-size=\"7.6\" fill=\"#334155\">• ताम्रसोपानं प्रार्थयत्</text>\n        <text x=\"10\" y=\"50\" font-size=\"7.6\" fill=\"#334155\">• ताम्रथाल्यां भोजनम् ऐच्छत्</text>\n        <text x=\"10\" y=\"66\" font-size=\"8\" font-weight=\"bold\" fill=\"#047857\">• लघुत्तमां मञ्जूषां नीतवती</text>\n        <rect x=\"10\" y=\"78\" width=\"140\" height=\"72\" rx=\"4\" fill=\"#ffffff\" stroke=\"#bbf7d0\"/>\n        <text x=\"16\" y=\"96\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#15803d\">फलम्: महार्हाणि हीरकाणि</text>\n        <text x=\"16\" y=\"112\" font-size=\"7.4\" fill=\"#166534\">धनिका सञ्जाता</text>\n        <text x=\"16\" y=\"128\" font-size=\"7.8\" font-weight=\"bold\" fill=\"#059669\">✅ 'सन्तोषः परमो लाभः'</text>\n        <text x=\"16\" y=\"142\" font-size=\"6.8\" fill=\"#64748b\">(निःस्वार्थतायाः पुरस्कारः)</text>\n\n        <!-- Box B: Lubdha Balika -->\n        <rect x=\"170\" y=\"0\" width=\"160\" height=\"162\" rx=\"6\" fill=\"#fef2f2\" stroke=\"#fca5a5\"/>\n        <text x=\"180\" y=\"20\" font-size=\"8.8\" font-weight=\"bold\" fill=\"#991b1b\">गर्विता लुब्धा बालिका:</text>\n        <text x=\"180\" y=\"36\" font-size=\"7.6\" fill=\"#334155\">• स्वर्णसोपानम् अयाचत्</text>\n        <text x=\"180\" y=\"50\" font-size=\"7.6\" fill=\"#334155\">• स्वर्णथाल्यां भोजनं दम्भात्</text>\n        <text x=\"180\" y=\"66\" font-size=\"8\" font-weight=\"bold\" fill=\"#b91c1c\">• बृहत्तमां मञ्जूषां गृहीतवती</text>\n        <rect x=\"180\" y=\"78\" width=\"140\" height=\"72\" rx=\"4\" fill=\"#ffffff\" stroke=\"#fecaca\"/>\n        <text x=\"186\" y=\"96\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#dc2626\">फलम्: भीषणः कृष्णसर्पः</text>\n        <text x=\"186\" y=\"112\" font-size=\"7.4\" fill=\"#991b1b\">लोभस्य फलम् आसादितम्</text>\n        <text x=\"186\" y=\"128\" font-size=\"7.8\" font-weight=\"bold\" fill=\"#b91c1c\">❌ 'लोभः पापस्य कारणम्'</text>\n        <text x=\"186\" y=\"142\" font-size=\"6.8\" fill=\"#64748b\">(लोभं परित्यक्तवती)</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (NCERT Exercises & CBSE Marking Rubrics 2026-27)</div>\n\n  <!-- अभ्यासः १ -->\n  <div class=\"q-card\" id=\"c9sk_ch2_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch2_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरं लिखत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः (Direct Case-Ending Precision)</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितानां प्रश्नानाम् उत्तराणि एकपदेन लिखत:<br>\n        (क) माता काम् आदिशत्?<br>\n        (ख) स्वर्णकाकः कान् अखादत्?<br>\n        (ग) प्रासादः कीदृशः वर्तते?<br>\n        (घ) गृहमागत्य तया का समुद्घाटिता?<br>\n        (ङ) लोभाविष्टा बालिका कीदृशीं मञ्जूषां नयति?\n      </div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क)</strong> <span class=\"ans-highlight\">पुत्रीम्</span> (दुहितरम्)</p>\n            <p><strong>(ख)</strong> <span class=\"ans-highlight\">तण्डुलान्</span></p>\n            <p><strong>(ग)</strong> <span class=\"ans-highlight\">स्वर्णमयः</span></p>\n            <p><strong>(घ)</strong> <span class=\"ans-highlight\">मञ्जूषा</span> (पेटिका)</p>\n            <p><strong>(ङ)</strong> <span class=\"ans-highlight\">बृहत्तमाम्</span> (विशालत्तमाम्)</p>\n          </div>\n          <div class=\"hi-trans\">\n            <strong>हिन्दी व्याख्या:</strong><br>\n            • (क) माँ ने अपनी पुत्री को चावलों की रक्षा करने का आदेश दिया।<br>\n            • (ख) सोने के कौवे ने धूप में रखे चावलों को खा लिया।<br>\n            • (ग) पीपल के वृक्ष के ऊपर बना महल सोने का (स्वर्णमय) था।<br>\n            • (घ) घर आकर विनम्र बालिका ने संदूक (मञ्जूषा) खोली।<br>\n            • (ङ) लालची लड़की सबसे बड़ी पेटी उठाकर ले गई।\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(क) ‘पुत्रीम्’ शुद्ध द्वितीया-विभक्तियुक्तपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ख) ‘तण्डुलान्’ द्वितीया-बहुवचनपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ग) ‘स्वर्णमयः’ प्रथमा-विशेषणपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(घ) ‘मञ्जूषा’ शुद्ध स्त्रीलिंगपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ङ) ‘बृहत्तमाम्’ तमप्-प्रत्ययान्तपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः २ -->\n  <div class=\"q-card\" id=\"c9sk_ch2_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch2_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-ङ) — संस्कृतभाषया पूर्णवाक्येन उत्तरत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः (Full Sentence with Textual Accuracy)</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितानां प्रश्नानाम् उत्तराणि संस्कृतभाषया लिखत:<br>\n        (क) निर्धनायाः वृद्धायाः दुहिता कीदृशी आसीत्?<br>\n        (ख) बालिकया पूर्वं कीदृशः काकः न दृष्टः आसीत्?<br>\n        (ग) निर्धनायाः दुहिता मञ्जूषायां कानि अपश्यत्?<br>\n        (घ) बालिका किं दृष्ट्वा आश्चर्यचकिता जाता?<br>\n        (ङ) गर्विता बालिका कीदृशं सोपानम् अयाचत् कीदृशं च प्राप्नोत्?\n      </div>\n      <div class=\"q-marks\">१ × ५ = ५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क)</strong> निर्धनायाः वृद्धायाः दुहिता <strong>विनम्रा मनोहरा चासीत्</strong>।</p>\n            <p><strong>(ख)</strong> बालिकया पूर्वं <strong>स्वर्णपक्षः रजतचञ्चुः स्वर्णकाकः</strong> न दृष्टः आसीत्।</p>\n            <p><strong>(ग)</strong> निर्धनायाः दुहिता मञ्जूषायां <strong>महार्हाणि हीरकाणि</strong> (बहुमूल्यानि रत्नानि) अपश्यत्।</p>\n            <p><strong>(घ)</strong> बालिका वृक्षस्योपरि <strong>स्वर्णमयं प्रासादं</strong> दृष्ट्वा आश्चर्यचकिता जाता।</p>\n            <p><strong>(ङ)</strong> गर्विता बालिका <strong>स्वर्णमयं सोपानम् अयाचत्, परं स्वर्णकाकः तस्यै ताम्रमयं सोपानमेव प्रायच्छत्</strong>।</p>\n          </div>\n          <div class=\"hi-trans\">\n            <strong>हिन्दी व्याख्या:</strong><br>\n            • (क) निर्धन वृद्धा की पुत्री स्वभाव से अत्यंत विनम्र और सुंदर थी।<br>\n            • (ख) बालिका ने इससे पूर्व सोने के पंखों और चाँदी की चोंच वाला ऐसा अनोखा स्वर्णकाक कभी नहीं देखा था।<br>\n            • (ग) निर्धन बालिका ने सबसे छोटी संदूक खोली तो उसमें बहुमूल्य चमकते हुए हीरे देखे।<br>\n            • (घ) पीपल के विशाल वृक्ष पर सोने का महल देखकर वह बालिका आश्चर्यचकित रह गई।<br>\n            • (ङ) घमंडी बालिका ने सोने की सीढ़ी माँगी, लेकिन कौवे ने उसे तांबे की सीढ़ी ही प्रदान की।\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(क) ‘विनम्रा मनोहरा च’ विशेषणद्वयोल्लेखेन पूर्णवाक्यरचना</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ख) ‘स्वर्णपक्षः रजतचञ्चुः’ यथार्थोल्लेखेन वाक्यरचना</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ग) ‘महार्हाणि हीरकाणि’ शुद्ध द्वितीया-बहुवचनपदप्रयोगः</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(घ) ‘स्वर्णमयं प्रासादम्’ कर्मपदप्रयोगः</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ङ) स्वर्ण-ताम्र-उभयोः सोपानयोः स्पष्टोल्लेखः</span><span class=\"marking-marks\">१ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ३ -->\n  <div class=\"q-card\" id=\"c9sk_ch2_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch2_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — अधोलिखितानां पदानां विलोमपदं लिखत</span>\n        <span class=\"word-limit-pill\">सटीक विलोमपदानि</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितानां पदानां विलोमपदं पाठात् चित्वा लिखत:<br>\n        (क) पश्चात्<br>\n        (ख) हसितुम्<br>\n        (ग) अधः<br>\n        (घ) श्वेतः<br>\n        (ङ) सूर्योदयः<br>\n        (च) सुप्तः\n      </div>\n      <div class=\"q-marks\">१/२ × ६ = ३ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क) पश्चात्</strong> (बाद में) $\times$ <span class=\"ans-highlight\">पूर्वं / प्राक्</span> (पहले)</p>\n            <p><strong>(ख) हसितुम्</strong> (हँसने के लिए) $\times$ <span class=\"ans-highlight\">रोदितुम्</span> (रोने के लिए)</p>\n            <p><strong>(ग) अधः</strong> (नीचे) $\times$ <span class=\"ans-highlight\">उपरि</span> (ऊपर)</p>\n            <p><strong>(घ) श्वेतः</strong> (सफेद) $\times$ <span class=\"ans-highlight\">कृष्णः</span> (काला)</p>\n            <p><strong>(ङ) सूर्योदयः</strong> (सूरज निकलना) $\times$ <span class=\"ans-highlight\">सूर्यास्तः</span> (सूरज डूबना)</p>\n            <p><strong>(च) सुप्तः</strong> (सोया हुआ) $\times$ <span class=\"ans-highlight\">प्रबुद्धः / जाग्रतः</span> (जागा हुआ)</p>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् शुद्ध-विलोमपदलेखनाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ४ -->\n  <div class=\"q-card\" id=\"c9sk_ch2_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch2_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — सन्धिं कुरुत</span>\n        <span class=\"word-limit-pill\">नियमसम्मत सन्धियुक्त पदम्</span>\n      </div>\n      <div class=\"q-text\">\n        सन्धिं कुरुत:<br>\n        (१) नि + अवसत् = _____<br>\n        (२) सूर्य + उदयः = _____<br>\n        (३) वृक्षस्य + उपरि = _____<br>\n        (४) हि + अकारयत् = _____<br>\n        (५) च + एकाकिनी = _____<br>\n        (६) इति + उक्त्वा = _____<br>\n        (७) प्रति + अवदत् = _____<br>\n        (८) प्र + उक्तम् = _____<br>\n        (९) अत्र + एव = _____<br>\n        (१०) तत्र + उपस्थिता = _____<br>\n        (११) यथा + इच्छम् = _____\n      </div>\n      <div class=\"q-marks\">१/२ × ११ = ५.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p>(१) नि + अवसत् = <span class=\"ans-highlight\">न्यवसत्</span> <em>(यण्-स्वरसन्धिः: इ/ई + अ &rarr; य् + अ)</em></p>\n            <p>(२) सूर्य + उदयः = <span class=\"ans-highlight\">सूर्योदयः</span> <em>(गुण-स्वरसन्धिः: अ + उ &rarr; ओ)</em></p>\n            <p>(३) वृक्षस्य + उपरि = <span class=\"ans-highlight\">वृक्षस्योपरि</span> <em>(गुण-स्वरसन्धिः: अ + उ &rarr; ओ)</em></p>\n            <p>(४) हि + अकारयत् = <span class=\"ans-highlight\">ह्यकारयत्</span> <em>(यण्-स्वरसन्धिः: इ + अ &rarr; य् + अ)</em></p>\n            <p>(५) च + एकाकिनी = <span class=\"ans-highlight\">चैकाकिनी</span> <em>(वृद्धि-स्वरसन्धिः: अ + ए &rarr; ऐ)</em></p>\n            <p>(६) इति + उक्त्वा = <span class=\"ans-highlight\">इत्युक्त्वा</span> <em>(यण्-स्वरसन्धिः: इ + उ &rarr; यु)</em></p>\n            <p>(७) प्रति + अवदत् = <span class=\"ans-highlight\">प्रत्यवदत्</span> <em>(यण्-स्वरसन्धिः: इ + अ &rarr; य् + अ)</em></p>\n            <p>(८) प्र + उक्तम् = <span class=\"ans-highlight\">प्रोक्तम्</span> <em>(गुण-स्वरसन्धिः: अ + उ &rarr; ओ)</em></p>\n            <p>(९) अत्र + एव = <span class=\"ans-highlight\">अत्रैव</span> <em>(वृद्धि-स्वरसन्धिः: अ + ए &rarr; ऐ)</em></p>\n            <p>(१०) तत्र + उपस्थिता = <span class=\"ans-highlight\">तत्रोपस्थिता</span> <em>(गुण-स्वरसन्धिः: अ + उ &rarr; ओ)</em></p>\n            <p>(११) यथा + इच्छम् = <span class=\"ans-highlight\">यथेच्छम्</span> <em>(गुण-स्वरसन्धिः: आ + इ &rarr; ए)</em></p>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् शुद्ध-सन्धियुक्तपदे</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ५ -->\n  <div class=\"q-card\" id=\"c9sk_ch2_q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch2_q5')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ५ — स्थूलपदान्यधिकृत्य प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">प्रश्नवाचक-चिह्नयुक्त (?) पूर्णवाक्यम्</span>\n      </div>\n      <div class=\"q-text\">\n        स्थूलपदान्यधिकृत्य प्रश्ननिर्माणं कुरुत:<br>\n        (क) ग्रामे <u>निर्धना स्त्री</u> अवसत्।<br>\n        (ख) <u>स्वर्णकाकं</u> निवारयन्ती बालिका प्रार्थयत्।<br>\n        (ग) <u>सूर्योदयात्</u> पूर्वमेव बालिका तत्रोपस्थिता।<br>\n        (घ) बालिका <u>निर्धनमातुः</u> दुहिता आसीत्।<br>\n        (ङ) लुब्धा वृद्धा <u>स्वर्णकाकस्य</u> रहस्यमभिज्ञातवती।\n      </div>\n      <div class=\"q-marks\">१ × ५ = ५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क)</strong> ग्रामे <strong>का</strong> अवसत्? <em>(स्त्रीलिंग-प्रथमा-एकवचनम्)</em></p>\n            <p><strong>(ख)</strong> <strong>कम्</strong> निवारयन्ती बालिका प्रार्थयत्? <em>(पुंल्लिङ्ग-द्वितीया-एकवचनम्)</em></p>\n            <p><strong>(ग)</strong> <strong>कस्मात्</strong> पूर्वमेव बालिका तत्रोपस्थिता? <em>(पुंल्लिङ्ग-पञ्चमी-एकवचनम् अथवा 'कदा')</em></p>\n            <p><strong>(घ)</strong> बालिका <strong>कस्याः</strong> दुहिता आसीत्? <em>(स्त्रीलिंग-षष्ठी-एकवचनम्)</em></p>\n            <p><strong>(ङ)</strong> लुब्धा वृद्धा <strong>कस्य</strong> रहस्यमभिज्ञातवती? <em>(पुंल्लिङ्ग-षष्ठी-एकवचनम्)</em></p>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-किम्-रूपप्रयोगार्थं तथा पूर्णवाक्ये ‘?’ चिह्नाय</span><span class=\"marking-marks\">१ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ६ -->\n  <div class=\"q-card\" id=\"c9sk_ch2_q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch2_q6')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ६ — प्रकृतिमप्रत्ययं संयोज्य/विभज्य लिखत</span>\n        <span class=\"word-limit-pill\">धातु-प्रत्यय-संयोजनम्</span>\n      </div>\n      <div class=\"q-text\">\n        प्रकृति-प्रत्यय-संयोगं विभागं वा कुरुत:<br>\n        (१) वि + लोक् + ल्यप् = _____<br>\n        (२) नि + क्षिप् + ल्यप् = _____<br>\n        (३) आ + गम् + ल्यप् = _____<br>\n        (४) दृश् + क्त्वा = _____<br>\n        (५) शी + क्त्वा = _____<br>\n        (६) लघु + तमप् = _____<br>\n        (७) हस् + शतृ = _____\n      </div>\n      <div class=\"q-marks\">१/२ × ७ = ३.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p>(१) वि + लोक् + ल्यप् = <span class=\"ans-highlight\">विलोक्य</span> <em>(देखकर)</em></p>\n            <p>(२) नि + क्षिप् + ल्यप् = <span class=\"ans-highlight\">निक्षिप्य</span> <em>(रखकर / फेंककर)</em></p>\n            <p>(३) आ + गम् + ल्यप् = <span class=\"ans-highlight\">आगम्य</span> <em>(आकर)</em></p>\n            <p>(४) दृश् + क्त्वा = <span class=\"ans-highlight\">दृष्ट्वा</span> <em>(देखकर)</em></p>\n            <p>(५) शी + क्त्वा = <span class=\"ans-highlight\">शयित्वा</span> <em>(सोकर)</em></p>\n            <p>(६) लघु + तमप् = <span class=\"ans-highlight\">लघुतमम् / लघुतमः</span> <em>(सबसे छोटा)</em></p>\n            <p>(७) हस् + शतृ = <span class=\"ans-highlight\">हसन् / हसन्ती</span> <em>(हँसता हुआ / हँसती हुई)</em></p>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् शुद्ध-प्रत्ययान्तरूपाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ७ -->\n  <div class=\"q-card\" id=\"c9sk_ch2_q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch2_q7')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ७ — कः/का कम्/कां कथयति?</span>\n        <span class=\"word-limit-pill\">कथन-वक्तृ-श्रोतृ-ज्ञानम्</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितानि कथनानि कः/का कम्/कां प्रति कथयति?<br>\n        (क) ‘पूर्वम् प्रातराशः क्रियताम्।’<br>\n        (ख) ‘सूर्यातपे तण्डुलान् खगेभ्यो रक्ष।’<br>\n        (ग) ‘तण्डुलान् मा भक्षय।’<br>\n        (घ) ‘अहं तुभ्यं तण्डुलमूल्यं दास्यामि।’<br>\n        (ङ) ‘भो नीचकाक! अहमागता, मह्यं तण्डुलमूल्यं प्रयच्छ।’\n      </div>\n      <div class=\"q-marks\">१ × ५ = ५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <table style=\"width:100%; border-collapse:collapse; margin:10px 0; font-size:0.9rem;\">\n            <thead>\n              <tr style=\"background:#f5f3ff; text-align:left; border-bottom:2px solid #ddd6fe;\">\n                <th style=\"padding:10px; color:#5b21b6;\">कथनम् (संवादः)</th>\n                <th style=\"padding:10px; color:#5b21b6;\">कः / का (वक्ता)</th>\n                <th style=\"padding:10px; color:#5b21b6;\">कम् / काम् (श्रोता)</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px;\">(क) ‘पूर्वम् प्रातराशः क्रियताम्।’</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">स्वर्णकाकः</td>\n                <td style=\"padding:9px; font-weight:700; color:#059669;\">बालिकाम् (निर्धनाम्)</td>\n              </tr>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px;\">(ख) ‘सूर्यातपे तण्डुलान् खगेभ्यो रक्ष।’</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">माता</td>\n                <td style=\"padding:9px; font-weight:700; color:#059669;\">पुत्रीम् (दुहितरम्)</td>\n              </tr>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px;\">(ग) ‘तण्डुलान् मा भक्षय।’</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">बालिका</td>\n                <td style=\"padding:9px; font-weight:700; color:#059669;\">स्वर्णकाकम्</td>\n              </tr>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px;\">(घ) ‘अहं तुभ्यं तण्डुलमूल्यं दास्यामि।’</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">स्वर्णकाकः</td>\n                <td style=\"padding:9px; font-weight:700; color:#059669;\">बालिकाम्</td>\n              </tr>\n              <tr>\n                <td style=\"padding:9px;\">(ङ) ‘भो नीचकाक! अहमागता, मह्यं तण्डुलमूल्यं प्रयच्छ।’</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">लुब्धा (गर्विता) बालिका</td>\n                <td style=\"padding:9px; font-weight:700; color:#059669;\">स्वर्णकाकम्</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वक्तृ-श्रोतृ-उभयोः शुद्ध-विभक्ति-सहित-लेखनाय प्रतिप्रश्नम्</span><span class=\"marking-marks\">१ अंकः (१/२ + १/२)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #7c3aed;\">\n        <div class=\"cbq-type\" style=\"color:#7c3aed;\">योग्यता-आधारितः प्रश्नः (NEP 2020 Competency HOTS Question)</div>\n        <div class=\"cbq-question\">\n          <strong>प्रश्नः:</strong> ‘स्वर्णकाकः’ इति कथायाः आधारेण स्पष्टीकुरुत यत् लोभस्य किं दुष्फलं भवति तथा च सन्तोषस्य कः लाभः? (शब्द-सीमा: ३०-४० शब्दाः | अंकाः: २)\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\">\n          <p>‘स्वर्णकाकः’ कथायाः सन्देशः अस्ति यत् ‘लोभः पापस्य कारणम्’ तथा ‘सन्तोषः परमो लाभः’। निर्धना बालिका स्वभावेन विनम्रा सन्तोषिणी चासीत्, अतः सा लघुत्तमां मञ्जूषां गृहीत्वापि अमूल्यानि हीरकाणि प्राप्तवती। अपरपक्षे गर्विता बालिका लोभवशात् स्वर्णसोपानम् ऐच्छत् बृहत्तमां मञ्जूषां च नीतवती, फलतः सा मञ्जूषातः केवलं भीषणं कृष्णसर्पं प्राप्य दुःखम् अन्वभवत्। अतः मानवेन लोभः सर्वथा त्याज्यः।</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Chapter Nav Buttons -->\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(1)\">← पूर्वः पाठः: भारतीवसन्तगीतिः (Ch 1)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\">अग्रिमः पाठः: गोदोहनम् (Ch 3) →</button>\n  </div>\n</section>";

window.PRELOADED_CHAPTERS_C9SK["3"] = "<section class=\"chapter-section\" id=\"ch3\" data-book=\"shemushi\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">पाठः ३</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">नाट्यभागः (संवादः) • शेमुषी प्रथमो भागः (Code 122)</div>\n      <h2>तृतीयः पाठः — गोदोहनम्</h2>\n      <p class=\"ch-author\">रचयिता: श्री कृष्णचन्द्र त्रिपाठी (नाट्यसङ्ग्रहः: ‘चतुर्व्यूहम्’)</p>\n    </div>\n  </div>\n\n  <div class=\"theme-card\">\n    <div class=\"theme-header\">\n      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"><path d=\"M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z\"/><path d=\"M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z\"/></svg>\n      <span>पाठ-सारः एवं मुख्य-सन्देशः (Chapter Summary & Central Theme)</span>\n    </div>\n    <div class=\"theme-body\">\n      <p>प्रस्तुतोऽयं नाट्यांशः <strong>श्री-कृष्णचन्द्र-त्रिपाठिना</strong> विरचितात् ‘चतुर्व्यूहम्’ इति पुस्तकसङ्ग्रहात् सङ्क्षिप्तः सम्पादितश्च अस्ति। अस्मिन् नाटके चन्दन-मल्लिका-दम्पत्योः कथा वर्णिता अस्ति, यत्र चन्दनः ग्रामप्रमुखस्य गृहे मासान्ते आयोज्यमाने उत्सवे त्रिंशत्सेटकपरिमितं (३०० लीटर) दुग्धं विक्रीय धनवान् भवितुम् इच्छति। अतः सः मासपर्यन्तं धेनोः दुग्धदोहनं न करोति। मासान्ते यदा सः दोहनं कर्तुम् उद्यतो भवति, तदा धेनुः पादप्रहारेण तं रक्तरञ्जितं करोति, दुग्धबिन्दुरपि न लभ्यते।</p>\n      <p style=\"margin-top:8px;font-style:italic;color:#6b21a8;\"><strong>नीति-शिक्षा:</strong> <em>‘यद् अद्यतनं कार्यं तद् अद्यैव विधेयम्’</em> — यः जनः समयस्य सदुपयोगं न कृत्वा दैनिकं कार्यं मासान्ते एकत्र कर्तुम् इच्छति, सः लाभाय स्थाने महद् दुःखं हानिं च प्राप्नोति।</p>\n    </div>\n  </div>\n\n  <!-- Custom Educational SVG -->\n  \n  <div style=\"margin:22px 0; background:white; padding:18px; border-radius:14px; border:1.5px solid #ede9fe; box-shadow:0 3px 12px rgba(124,58,237,0.06);\">\n    <h3 style=\"font-size:1.02rem; font-weight:800; color:#5b21b6; margin-bottom:12px; display:flex; align-items:center; gap:8px; font-family:'Noto Sans Devanagari', sans-serif;\">\n      <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"2.2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\n      नाट्य-दर्शनम्: धेनु-नन्दिनी, मासपर्यन्तम् अदोहन-भ्रमः तथा कालस्य सदुपयोगः\n    </h3>\n    <svg viewBox=\"0 0 780 250\" style=\"width:100%; height:auto; font-family:'Noto Sans Devanagari', system-ui, sans-serif;\">\n      <!-- Panel 1: The False Plan & Greed -->\n      <rect x=\"15\" y=\"15\" width=\"375\" height=\"220\" rx=\"10\" fill=\"#eff6ff\" stroke=\"#bfdbfe\" stroke-width=\"1.5\"/>\n      <text x=\"32\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#1e40af\">१. चन्दनस्य दुग्धसञ्चयस्य अविवेकपूर्णः विचारः:</text>\n\n      <g transform=\"translate(30, 52)\">\n        <rect x=\"0\" y=\"0\" width=\"345\" height=\"162\" rx=\"8\" fill=\"#ffffff\" stroke=\"#dbeafe\"/>\n        <!-- Cow Motif / Nandini -->\n        <ellipse cx=\"65\" cy=\"60\" rx=\"35\" ry=\"24\" fill=\"#f8fafc\" stroke=\"#64748b\" stroke-width=\"2\"/>\n        <circle cx=\"95\" cy=\"45\" r=\"14\" fill=\"#f8fafc\" stroke=\"#64748b\" stroke-width=\"2\"/>\n        <text x=\"45\" y=\"64\" font-size=\"9\" font-weight=\"bold\" fill=\"#334155\">धेनुः नन्दिनी</text>\n\n        <!-- Pot -->\n        <path d=\"M 170 85 L 175 45 L 205 45 L 210 85 Z\" fill=\"#fef3c7\" stroke=\"#d97706\" stroke-width=\"2\"/>\n        <ellipse cx=\"190\" cy=\"45\" rx=\"15\" ry=\"4\" fill=\"#fef08a\" stroke=\"#d97706\"/>\n        <text x=\"175\" y=\"70\" font-size=\"8\" font-weight=\"bold\" fill=\"#b45309\">घटः</text>\n\n        <!-- Description -->\n        <text x=\"120\" y=\"35\" font-size=\"8.8\" font-weight=\"bold\" fill=\"#1d4ed8\">• उमायाः पितामहस्य उत्सवः (३०० लीटर)</text>\n        <text x=\"120\" y=\"50\" font-size=\"8\" fill=\"#475569\">• 'मासान्ते एकत्रैव दुग्धं दोहयिष्यामि'</text>\n        <text x=\"120\" y=\"65\" font-size=\"8\" fill=\"#475569\">• दैनिक-दोहनं स्थगितम्, केवलं सेवा</text>\n\n        <!-- Warning Callout -->\n        <rect x=\"15\" y=\"102\" width=\"315\" height=\"48\" rx=\"5\" fill=\"#fef2f2\" stroke=\"#fca5a5\"/>\n        <text x=\"25\" y=\"120\" font-size=\"8.4\" font-weight=\"bold\" fill=\"#b91c1c\">भ्रान्त-धारणा: 'मासपर्यन्तं दुग्धं सुरक्षिता स्थास्यति'</text>\n        <text x=\"25\" y=\"136\" font-size=\"7.6\" fill=\"#7f1d1d\">वस्तुस्थितिः: शरीरे दुग्धं शुष्कं भवति, धेनुः च कष्टम् अनुभवति!</text>\n      </g>\n\n      <!-- Panel 2: Climax & The Moral Verse on Time -->\n      <rect x=\"405\" y=\"15\" width=\"360\" height=\"220\" rx=\"10\" fill=\"#fdf4ff\" stroke=\"#f0abfc\" stroke-width=\"1.5\"/>\n      <text x=\"422\" y=\"38\" font-size=\"12\" font-weight=\"bold\" fill=\"#86198f\">२. कर्मफलम् एवं कालस्य शाश्वत-नियमः:</text>\n\n      <g transform=\"translate(420, 52)\">\n        <rect x=\"0\" y=\"0\" width=\"330\" height=\"162\" rx=\"8\" fill=\"#ffffff\" stroke=\"#f5d0fe\"/>\n        <!-- Result Box -->\n        <rect x=\"12\" y=\"12\" width=\"306\" height=\"52\" rx=\"5\" fill=\"#fee2e2\" stroke=\"#fca5a5\"/>\n        <text x=\"20\" y=\"30\" font-size=\"8.5\" font-weight=\"bold\" fill=\"#dc2626\">उत्सवदिने परिणामः: नन्दिन्याः पादप्रहारः!</text>\n        <text x=\"20\" y=\"44\" font-size=\"7.8\" fill=\"#991b1b\">• चन्दनः रक्तरञ्जितः अभवत्, दुग्धबिन्दुरपि न प्राप्ता</text>\n        <text x=\"20\" y=\"56\" font-size=\"7.5\" fill=\"#475569\">• धनिकभवनस्य स्वप्नः भग्नः, घटमूल्यमपि देयम्</text>\n\n        <!-- Golden Verse -->\n        <rect x=\"12\" y=\"72\" width=\"306\" height=\"78\" rx=\"5\" fill=\"#faf5ff\" stroke=\"#ddd6fe\"/>\n        <text x=\"20\" y=\"88\" font-size=\"8.2\" font-weight=\"bold\" fill=\"#6b21a8\">📖 नीत्युपदेशः (सुभाषितम्):</text>\n        <text x=\"20\" y=\"104\" font-size=\"7.6\" font-style=\"italic\" fill=\"#581c87\">\"आदानस्य प्रदानस्य कर्तव्यस्य च कर्मणः।</text>\n        <text x=\"20\" y=\"118\" font-size=\"7.6\" font-style=\"italic\" fill=\"#581c87\"> क्षिप्रमक्रियमाणस्य कालः पिबति तद्रसम्॥\"</text>\n        <text x=\"20\" y=\"136\" font-size=\"8\" font-weight=\"bold\" fill=\"#059669\">✅ 'अद्यतनं कार्यं तद् अद्यैव विधेयम्' (विलम्बः विनाशाय)</text>\n      </g>\n    </svg>\n  </div>\n\n\n  <div class=\"ex-div\">📖 एनसीईआरटी अभ्यास-प्रश्नोत्तराणि एवं सीबीएसई अंक-योजना (NCERT Exercises & CBSE Marking Rubrics 2026-27)</div>\n\n  <!-- अभ्यासः १ -->\n  <div class=\"q-card\" id=\"c9sk_ch3_q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch3_q1')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः १ (क-ङ) — एकपदेन उत्तरं लिखत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १-२ शब्दाः (Direct Case Precision)</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितानां प्रश्नानाम् उत्तराणि एकपदेन लिखत:<br>\n        (क) मल्लिका पूजार्थं सखीभिः सह कुत्र गच्छति स्म?<br>\n        (ख) उमायाः पितामहेन कति सेटकपरिमितं दुग्धम् अपेक्ष्यते स्म?<br>\n        (ग) कुम्भकारः घटान् किमर्थं रचयति?<br>\n        (घ) कानि चन्दनस्य जिह्वालोलुपतां वर्धन्ते स्म?<br>\n        (ङ) नन्दिन्याः पादप्रहारैः कः रक्तरञ्जितः अभवत्?\n      </div>\n      <div class=\"q-marks\">१/२ × ५ = २.५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क)</strong> <span class=\"ans-highlight\">काशीविश्वनाथमन्दिरम्</span> (काशीम्)</p>\n            <p><strong>(ख)</strong> <span class=\"ans-highlight\">त्रिशत-सेटकपरिमितम्</span> (३०० लीटर / त्रिंशदुत्तरशतम्)</p>\n            <p><strong>(ग)</strong> <span class=\"ans-highlight\">जीविकाहेतोः</span> (आजीविकार्थम्)</p>\n            <p><strong>(घ)</strong> <span class=\"ans-highlight\">मोदकानि</span> (लड्डूकम्)</p>\n            <p><strong>(ङ)</strong> <span class=\"ans-highlight\">चन्दनः</span></p>\n          </div>\n          <div class=\"hi-trans\">\n            <strong>हिन्दी व्याख्या:</strong><br>\n            • (क) मल्लिका पूजा के लिए अपनी सखियों के साथ काशी विश्वनाथ मंदिर जा रही थी।<br>\n            • (ख) उमा के दादाजी के यहाँ महीने के अंत में तीन सौ लीटर (त्रिशत-सेटक) दूध की आवश्यकता थी।<br>\n            • (ग) कुम्हार अपनी आजीविका चलाने के लिए मिट्टी के घड़े बनाता है।<br>\n            • (घ) मल्लिका द्वारा बनाए गए सुगंधित मोदक (लड्डू) चंदन की जीभ के स्वाद-लोभ को बढ़ा रहे थे।<br>\n            • (ङ) गाय (नन्दिनी) के लात मारने से चंदन लहूलुहान (रक्तरञ्जित) हो गया।\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(क) ‘काशीविश्वनाथमन्दिरम्’ शुद्ध द्वितीया-स्थानवाचकपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ख) ‘त्रिशत-सेटकपरिमितम्’ संख्यावाचकपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ग) ‘जीविकाहेतोः’ पञ्चमी-षष्ठीपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(घ) ‘मोदकानि’ नपुंसकलिंग-प्रथमा-बहुवचनपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ङ) ‘चन्दनः’ प्रथमा-एकवचनपदाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः २ -->\n  <div class=\"q-card\" id=\"c9sk_ch3_q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch3_q2')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः २ (क-ङ) — पूर्णवाक्येन उत्तरं लिखत</span>\n        <span class=\"word-limit-pill\">शब्द-सीमा: १०-२० शब्दाः (Full Sentence with Textual Concord)</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितानां प्रश्नानाम् उत्तराणि संस्कृतभाषया पूर्णवाक्येन लिखत:<br>\n        (क) मल्लिका चन्दनश्च मासपर्यन्तं धेनोः सेवां कथम् अकुरुताम्?<br>\n        (ख) कालः कस्य रसं पिबति?<br>\n        (ग) घटमूल्यार्थं यदा मल्लिका स्वाभूषणं दातुं प्रयतते तदा कुम्भकारः किं वदति?<br>\n        (घ) मल्लिकया किं दृष्ट्वा धेनोः ताडनस्य वास्तविकं कारणं ज्ञातम्?<br>\n        (ङ) मासपर्यन्तं धेनोः अदोहनस्य किं कारणमासीत्?\n      </div>\n      <div class=\"q-marks\">१ × ५ = ५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क)</strong> मल्लिका चन्दनश्च मासपर्यन्तं दुग्धदोहनं विहाय <strong>धेनोः घासादिकं गुडादिकं च भोजयतः, तिलकं कृत्वा तैलं लेपयतः, रात्रौ नीराजनेनापि तोषयतः च</strong>।</p>\n            <p><strong>(ख)</strong> <strong>क्षिप्रम् अक्रियमाणस्य आदानस्य, प्रदानस्य, कर्तव्यस्य च कर्मणः रसं कालः पिबति</strong>।</p>\n            <p><strong>(ग)</strong> कुम्भकारः वदति— <strong>\"पुत्रिके! नाहं पापकर्म करोमि। कथमपि नेच्छामि त्वाम् आभूषणविहीनां कर्तुम्। नयतु यथाभिलषितान् घटान्। दुग्धं विक्रीयैव घटमूल्यं ददातु।\"</strong></p>\n            <p><strong>(घ)</strong> मल्लिकया ज्ञातं यत्— <strong>मासपर्यन्तं दोहनं न कृतम्, अतः सा धेनुः तीव्रपीडाम् अनुभवति, अत एव सा पादाभ्यां प्रहरति</strong>।</p>\n            <p><strong>(ङ)</strong> मासपर्यन्तं धेनोः अदोहनस्य कारणम् आसीत् यत्— <strong>मासान्ते उत्सवे एकत्रैव त्रिंशत्सेटकपरिमितं दुग्धं विक्रीय चन्दनः धनिकः भवितुम् ऐच्छत्</strong>।</p>\n          </div>\n          <div class=\"hi-trans\">\n            <strong>हिन्दी व्याख्या:</strong><br>\n            • (क) मल्लिका और चंदन महीने भर दूध दुहना छोड़कर गाय को घास और गुड़ खिलाते, तेल लगाते, तिलक करते और आरती उतारकर प्रसन्न करते रहे।<br>\n            • (ख) समय पर न किए जाने वाले लेन-देन और कर्तव्य कर्मों का सारा फल और आनंद समय रूपी काल पी जाता है (नष्ट कर देता है)।<br>\n            • (ग) कुम्हार ने कहा कि मैं तुम्हें गहनों से रहित नहीं करना चाहता; तुम स्वेच्छा से घड़े ले जाओ और दूध बेचकर ही मूल्य चुका देना।<br>\n            • (घ) मल्लिका ने समझा कि महीने भर दूध न निकाले जाने से गाय असहनीय पीड़ा में थी, इसलिए वह लात मार रही थी।<br>\n            • (ङ) महीने भर गाय को न दुहने का कारण चंदन का यह लालच था कि महीने के अंत में उत्सव पर 300 लीटर दूध एक साथ बेचकर वह अमीर बन जाएगा।\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(क) सेवायाः विधीनां (घास-गुडादि) यथार्थोल्लेखेन पूर्णवाक्यम्</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ख) श्लोकार्थानुसारं ‘आदानस्य प्रदानस्य कर्तव्यस्य कर्मणः’ उल्लेखः</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ग) कुम्भकारस्य कथनस्य (‘नाहं पापकर्म करोमि’) शुद्धोद्धरणम्</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(घ) धेनोः पीडानुभवस्य यथार्थोल्लेखेन वाक्यरचना</span><span class=\"marking-marks\">१ अंकः</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">(ङ) धनिकभवनस्य लोभकारणस्य प्रतिपादनम्</span><span class=\"marking-marks\">१ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ३ -->\n  <div class=\"q-card\" id=\"c9sk_ch3_q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch3_q3')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ३ — रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणम्</span>\n        <span class=\"word-limit-pill\">प्रश्नवाचक-चिह्नयुक्त (?) पूर्णवाक्यम्</span>\n      </div>\n      <div class=\"q-text\">\n        रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणं कुरुत:<br>\n        (क) मल्लिका <u>सखीभिः</u> सह धर्मयात्रायै गच्छति स्म।<br>\n        (ख) चन्दनः दुग्धदोहनं कृत्वा एव <u>स्वप्रातराशस्य</u> प्रबन्धम् अकरोत्।<br>\n        (ग) <u>मोदकानि</u> पूजानिमित्तानि रचितानि आसन्।<br>\n        (घ) मल्लिका स्वपतिं <u>चतुरतमं</u> मन्यते।<br>\n        (ङ) <u>नन्दिनी</u> पादाभ्यां ताडयित्वा चन्दनं रक्तरञ्जितं करोति।\n      </div>\n      <div class=\"q-marks\">१ × ५ = ५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(क)</strong> मल्लिका <strong>काभिः</strong> सह धर्मयात्रायै गच्छति स्म? <em>(स्त्रीलिंग-तृतीया-बहुवचनम्)</em></p>\n            <p><strong>(ख)</strong> चन्दनः दुग्धदोहनं कृत्वा एव <strong>कस्य</strong> प्रबन्धम् अकरोत्? <em>(पुंल्लिङ्ग-षष्ठी-एकवचनम्)</em></p>\n            <p><strong>(ग)</strong> <strong>कानि</strong> पूजानिमित्तानि रचितानि आसन्? <em>(नपुंसकलिंग-प्रथमा-बहुवचनम्)</em></p>\n            <p><strong>(घ)</strong> मल्लिका स्वपतिं <strong>कीदृशं</strong> मन्यते? <em>(विशेषणवाचक-प्रश्नपदम्)</em></p>\n            <p><strong>(ङ)</strong> <strong>का</strong> पादाभ्यां ताडयित्वा चन्दनं रक्तरञ्जितं करोति? <em>(स्त्रीलिंग-प्रथमा-एकवचनम्)</em></p>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक-किम्-रूपप्रयोगार्थं तथा पूर्णवाक्ये ‘?’ चिह्नाय</span><span class=\"marking-marks\">१ अंकः प्रतिप्रश्नम्</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ४ -->\n  <div class=\"q-card\" id=\"c9sk_ch3_q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch3_q4')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ४ — मञ्जूषातः भावार्थे रिक्तस्थानपूर्तिः</span>\n        <span class=\"word-limit-pill\">उचितपदचयनम्</span>\n      </div>\n      <div class=\"q-text\">\n        मञ्जूषायाः सहायतया भावार्थे रिक्तस्थानानि पूरयत:<br>\n        [मञ्जूषा: गृहव्यवस्थायै, उत्पादयेत्, समर्थकः, धर्मयात्रायाः, मङ्गलकामनाम्, कल्याणकारिणः]<br><br>\n        यदा चन्दनः स्वपत्न्याः काशीविश्वनाथं प्रति (१) _____ विषये जानाति, तदा सः क्रोधितः न भवति, यत् तस्याः पत्नी तं (२) _____ कथयित्वा सखीभिः सह भ्रमणाय गच्छति; अपि तु तस्याः यात्रायाः कृते (३) _____ कुर्वन् कथयति यत् तव मार्गाः शिवाः अर्थात् (४) _____ भवन्तु। मार्गे काचिदपि बाधा तव कृते समस्यां न (५) _____। एतेन सिध्यति यत् चन्दनः नारीस्वतन्त्रतायाः (६) _____ आसीत्।\n      </div>\n      <div class=\"q-marks\">१/२ × ६ = ३ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p>यदा चन्दनः स्वपत्न्याः काशीविश्वनाथं प्रति <strong>(१) धर्मयात्रायाः</strong> विषये जानाति, तदा सः क्रोधितः न भवति, यत् तस्याः पत्नी तं <strong>(२) गृहव्यवस्थायै</strong> कथयित्वा सखीभिः सह भ्रमणाय गच्छति; अपि तु तस्याः यात्रायाः कृते <strong>(३) मङ्गलकामनाम्</strong> कुर्वन् कथयति यत् तव मार्गाः शिवाः अर्थात् <strong>(४) कल्याणकारिणः</strong> भवन्तु। मार्गे काचिदपि बाधा तव कृते समस्यां न <strong>(५) उत्पादयेत्</strong>। एतेन सिध्यति यत् चन्दनः नारीस्वतन्त्रतायाः <strong>(६) समर्थकः</strong> आसीत्।</p>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् शुद्ध-रिक्तस्थाने</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ५ -->\n  <div class=\"q-card\" id=\"c9sk_ch3_q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch3_q5')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ५ — घटनाक्रमानुसारं वाक्यानि लिखत</span>\n        <span class=\"word-limit-pill\">कथाक्रम-संयोजनम्</span>\n      </div>\n      <div class=\"q-text\">\n        घटनाक्रमानुसारं वाक्यानि पुनः लिखत:<br>\n        (क) सा सखीभिः सह तीर्थयात्रायै काशीविश्वनाथमन्दिरं प्रति गच्छति।<br>\n        (ख) उभौ नन्दिन्याः सर्वविधपरिचर्यां कुरुतः।<br>\n        (ग) उमा मासान्ते उत्सवार्थं दुग्धस्य आवश्यकताविषये चन्दनं सूचयति।<br>\n        (घ) मल्लिका पूजार्थं मोदकानि रचयति।<br>\n        (ङ) उत्सवदिने यदा दोग्धुं प्रयत्नं करोति तदा नन्दिनी पादेन प्रहरति।<br>\n        (च) चन्दनस्य पत्नी तीर्थयात्रां समाप्य गृहं प्रत्यागच्छति।<br>\n        (छ) चन्दनः उत्सवसमये अधिकाधिकं दुग्धं प्राप्तुं मासपर्यन्तं दोहनं न करोति।<br>\n        (ज) कार्याणि समये करणीयानि इति चन्दनः नन्दिन्याः पादप्रहारेण अवगच्छति।\n      </div>\n      <div class=\"q-marks\">१/२ × ८ = ४ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>शुद्धः घटनाक्रमः (Correct Chronological Sequence):</strong></p>\n            <ol style=\"margin-left:22px; line-height:1.9;\">\n              <li><strong>(घ)</strong> मल्लिका पूजार्थं मोदकानि रचयति।</li>\n              <li><strong>(क)</strong> सा सखीभिः सह तीर्थयात्रायै काशीविश्वनाथमन्दिरं प्रति गच्छति।</li>\n              <li><strong>(ग)</strong> उमा मासान्ते उत्सवार्थं दुग्धस्य आवश्यकताविषये चन्दनं सूचयति।</li>\n              <li><strong>(च)</strong> चन्दनस्य पत्नी तीर्थयात्रां समाप्य गृहं प्रत्यागच्छति।</li>\n              <li><strong>(ख)</strong> उभौ नन्दिन्याः सर्वविधपरिचर्यां कुरुतः।</li>\n              <li><strong>(छ)</strong> चन्दनः उत्सवसमये अधिकाधिकं दुग्धं प्राप्तुं मासपर्यन्तं दोहनं न करोति।</li>\n              <li><strong>(ङ)</strong> उत्सवदिने यदा दोग्धुं प्रयत्नं करोति तदा नन्दिनी पादेन प्रहरति।</li>\n              <li><strong>(ज)</strong> कार्याणि समये करणीयानि इति चन्दनः नन्दिन्याः पादप्रहारेण अवगच्छति।</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्य वाक्यस्य यथार्थक्रमस्थापनाय</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ६ -->\n  <div class=\"q-card\" id=\"c9sk_ch3_q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch3_q6')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ६ — कः/का कम्/कां प्रति कथयति?</span>\n        <span class=\"word-limit-pill\">संवाद-वक्तृ-श्रोतृ-ज्ञानम्</span>\n      </div>\n      <div class=\"q-text\">\n        अधोलिखितानि वाक्यानि कः/का कम्/कां प्रति कथयति इति प्रदत्तस्थाने लिखत:<br>\n        (क) ‘धन्यवाद मातुल! याम्यधुना।’<br>\n        (ख) ‘त्रिंशत्सेटकपरिमितं दुग्धम्? शोभनम्, व्यवस्था भविष्यति।’<br>\n        (ग) ‘मूल्यं तु दुग्धं विक्रीयैव दातुं शक्यते।’<br>\n        (घ) ‘पुत्रिके! नाहं पापकर्म करोमि। कथमपि नेच्छामि त्वाम् आभूषणविहीनां कर्तुम्।’<br>\n        (ङ) ‘देवि! मयापि ज्ञातं यदस्माभिः सर्वथा अनुचितमेव कृतम्।’\n      </div>\n      <div class=\"q-marks\">१ × ५ = ५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <table style=\"width:100%; border-collapse:collapse; margin:10px 0; font-size:0.9rem;\">\n            <thead>\n              <tr style=\"background:#f5f3ff; text-align:left; border-bottom:2px solid #ddd6fe;\">\n                <th style=\"padding:10px; color:#5b21b6;\">वाक्यम् (संवादः)</th>\n                <th style=\"padding:10px; color:#5b21b6;\">कः / का (वक्ता)</th>\n                <th style=\"padding:10px; color:#5b21b6;\">कम् / काम् (श्रोता)</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px;\">(क) ‘धन्यवाद मातुल! याम्यधुना।’</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">उमा</td>\n                <td style=\"padding:9px; font-weight:700; color:#059669;\">चन्दनम्</td>\n              </tr>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px;\">(ख) ‘त्रिंशत्सेटकपरिमितं दुग्धम्? शोभनम्, व्यवस्था भविष्यति।’</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">चन्दनः</td>\n                <td style=\"padding:9px; font-weight:700; color:#059669;\">उमाम्</td>\n              </tr>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px;\">(ग) ‘मूल्यं तु दुग्धं विक्रीयैव दातुं शक्यते।’</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">चन्दनः</td>\n                <td style=\"padding:9px; font-weight:700; color:#059669;\">देवेशं (कुम्भकारम्)</td>\n              </tr>\n              <tr style=\"border-bottom:1px solid #f1f5f9;\">\n                <td style=\"padding:9px;\">(घ) ‘पुत्रिके! नाहं पापकर्म करोमि...’</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">देवेशः (कुम्भकारः)</td>\n                <td style=\"padding:9px; font-weight:700; color:#059669;\">मल्लिकाम्</td>\n              </tr>\n              <tr>\n                <td style=\"padding:9px;\">(ङ) ‘देवि! मयापि ज्ञातं यदस्माभिः सर्वथा अनुचितमेव कृतम्।’</td>\n                <td style=\"padding:9px; font-weight:700; color:#7c3aed;\">चन्दनः</td>\n                <td style=\"padding:9px; font-weight:700; color:#059669;\">मल्लिकाम्</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वक्तृ-श्रोतृ-उभयोः शुद्ध-विभक्ति-सहित-लेखनाय प्रतिप्रश्नम्</span><span class=\"marking-marks\">१ अंकः (१/२ + १/२)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- अभ्यासः ७ -->\n  <div class=\"q-card\" id=\"c9sk_ch3_q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('c9sk_ch3_q7')\">\n      <div class=\"q-head-left\">\n        <span class=\"q-num\">अभ्यासः ७ — सन्धिः एवं प्रकृति-प्रत्ययाः</span>\n        <span class=\"word-limit-pill\">व्याकरणसम्मत संयोजन-विभाजनम्</span>\n      </div>\n      <div class=\"q-text\">\n        <strong>(अ) पाठस्य आधारेण सन्धिं सन्धिच्छेदं वा कुरुत:</strong><br>\n        (१) शिवास्ते = _____<br>\n        (२) मनोहरः = _____<br>\n        (३) सप्ताहान्ते = _____<br>\n        (४) नेच्छामि = _____<br>\n        (५) अत्युत्तमः = _____<br><br>\n        <strong>(आ) अधोलिखितपदानां प्रकृतिं प्रत्ययं च संयोज्य विभज्य वा लिखत:</strong><br>\n        (१) करणीयम् = _____<br>\n        (२) वि + क्री + ल्यप् = _____<br>\n        (३) पठितम् = _____<br>\n        (४) ताडय् + क्त्वा = _____<br>\n        (५) दोग्धुम् = _____\n      </div>\n      <div class=\"q-marks\">१/२ × १० = ५ अंकाः</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ सीबीएसई मानक उत्तरम् (CBSE Model Answer & Detailed Explanation)</div>\n        <div class=\"answer-text\">\n          <div class=\"sans-ans-block\">\n            <p><strong>(अ) सन्धिः / सन्धिच्छेदः:</strong></p>\n            <p>(१) शिवास्ते = <span class=\"ans-highlight\">शिवाः + ते</span> <em>(विसर्ग-सत्वसन्धिः)</em></p>\n            <p>(२) मनोहरः = <span class=\"ans-highlight\">मनः + हरः</span> <em>(विसर्ग-उत्वसन्धिः)</em></p>\n            <p>(३) सप्ताहान्ते = <span class=\"ans-highlight\">सप्ताह + अन्ते</span> <em>(दीर्घ-स्वरसन्धिः)</em></p>\n            <p>(४) नेच्छामि = <span class=\"ans-highlight\">न + इच्छामि</span> <em>(गुण-स्वरसन्धिः)</em></p>\n            <p>(५) अत्युत्तमः = <span class=\"ans-highlight\">अति + उत्तमः</span> <em>(यण्-स्वरसन्धिः)</em></p>\n\n            <p style=\"margin-top:14px;\"><strong>(आ) प्रकृति-प्रत्यय-संयोजनम् / विभाजनम्:</strong></p>\n            <p>(१) करणीयम् = <span class=\"ans-highlight\">कृ + अनीयर्</span> <em>(नपुंसकलिंग-प्रथमा-एकवचनम्)</em></p>\n            <p>(२) वि + क्री + ल्यप् = <span class=\"ans-highlight\">विक्रीय</span> <em>(बेचकर)</em></p>\n            <p>(३) पठितम् = <span class=\"ans-highlight\">पठ् + क्त</span> <em>(पढ़ा हुआ)</em></p>\n            <p>(४) ताडय् + क्त्वा = <span class=\"ans-highlight\">ताडयित्वा</span> <em>(पीटकर / मारकर)</em></p>\n            <p>(५) दोग्धुम् = <span class=\"ans-highlight\">दुह् + तुमुन्</span> <em>(दूध दुहने के लिए)</em></p>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">📋 सीबीएसई चरणबद्ध अंक-विभाजन योजना (CBSE Step Marking Rubrics 2026-27)</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्येकस्मिन् शुद्ध-सन्धौ अथवा प्रत्ययरूपे</span><span class=\"marking-marks\">१/२ अंकः</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ Section -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 योग्यता-आधारिताः एवं मूल्यपरक-प्रश्नाः (CBSE Competency-Based / HOTS Questions)</span>\n      <span class=\"cbq-badge\">NEP 2020 Aligned</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #7c3aed;\">\n        <div class=\"cbq-type\" style=\"color:#7c3aed;\">योग्यता-आधारितः प्रश्नः (NEP 2020 Competency HOTS Question)</div>\n        <div class=\"cbq-question\">\n          <strong>प्रश्नः:</strong> ‘गोदोहनम्’ इति पाठस्य आधारेण कालप्रबन्धनस्य (Time Management) कर्तव्यपालनस्य च किं महत्वं वर्तते? संक्षेपेण प्रतिपादयत। (शब्द-सीमा: ३०-४० शब्दाः | अंकाः: २)\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तरं पश्यतु (Show Answer)</button>\n        <div class=\"cbq-answer\">\n          <p>अस्मिन् पाठे स्पष्टं प्रतिपादितं यत् ‘यद् अद्यतनं कार्यं तद् अद्यैव करणीयम्’। यः जनः क्षणिकलोभवशात् दैनिकं कार्यं मासान्ते एकत्र कर्तुम् इच्छति, सः कश्चिदपि लाभं न प्राप्नोति प्रत्युत सर्वं विनश्यति। श्लोकानुसारम् आदानस्य, प्रदानस्य, कर्तव्यस्य च कर्मणः यदि समये न क्रियते तर्हि तस्य सर्वं मधुरं फलं समयः एव हरति। अतः मानवेन आलस्यं त्यक्त्वा स्वकर्तव्यं यथासमयं सम्पादनीयम्।</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Chapter Nav Buttons -->\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(2)\">← पूर्वः पाठः: स्वर्णकाकः (Ch 2)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्षं प्रति (Back to Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\">अग्रिमः पाठः: सूक्तिमौक्तिकम् (Ch 4) →</button>\n  </div>\n</section>";
